README.md
preconditions.mjs
preflight.mjs
task.json
worker.mjs
// The release's gate: has the default branch moved since the last release went out?
//
// This is the task's own term because no built-in asks the question a release asks.
// `substantive-change` excludes task-authored commits, so a recount another task
// landed — a real change to what the site serves — would read as silence and never
// ship. `any-commit` includes them but measures a WINDOW, so the release's own bump
// commit keeps the window non-empty and every night re-releases the same bytes under
// a fresh version number.
//
// What ends that loop is position, not membership: the newest release commit is a
// high-water mark, and only what sits above it is unreleased. That is the same guard
// `[skip ci]` used to be, stated as a fact about the branch rather than as a flag on
// a commit message — nothing can accidentally re-arm a release by rewording a commit.

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { WRANGLER_CONFIGS, deployedPaths, parseWranglerConfig, wranglerConfigPath } from '../../lib.mjs';

// Which commits are the release's own, read structurally off the `Claudinite-Task:`
// trailer every task-authored commit carries. The worker stamps it from the queue's
// own `CLAUDINITE_PACK`/`CLAUDINITE_TASK`; the test holds this literal against the
// two directory names those are derived from.
export const RELEASE_TASK_ID = 'cloudflare-site/site-release';

// The `commits` signal lists the window's default-branch commits NEWEST FIRST — the
// order the GitHub commits API returns and the collector preserves — which is what
// makes "above the high-water mark" a slice.
export function unreleasedCommits(list = []) {
  const mark = list.findIndex((c) => c?.task === RELEASE_TASK_ID);
  return (mark === -1 ? list : list.slice(0, mark)).filter((c) => c?.task !== RELEASE_TASK_ID);
}

// Only a commit touching what the deploy ships needs releasing; the repo's own
// wrangler config says what that is. A term runs in its task's folder, so the repo
// is the job's workspace, or failing that the checkout holding that folder.
// A commit with no file list, or a repo whose config cannot be read here, counts:
// the release is where a missing or broken config is parked by name.
export function readDeployedPaths(root = repoRoot()) {
  if (!root) return null;
  const candidates = [...WRANGLER_CONFIGS];
  try {
    for (const entry of readdirSync(root, { withFileTypes: true })) {
      if (entry.isDirectory()) candidates.push(...WRANGLER_CONFIGS.map((name) => `${entry.name}/${name}`));
    }
  } catch {
    return null;
  }
  const configPath = wranglerConfigPath(candidates.filter((p) => existsSync(join(root, p))));
  if (!configPath) return null;
  const config = parseWranglerConfig(readFileSync(join(root, configPath), 'utf8'));
  return config ? deployedPaths(config, configPath) : null;
}

function repoRoot() {
  if (process.env.GITHUB_WORKSPACE) return process.env.GITHUB_WORKSPACE;
  for (let dir = process.cwd(); ; dir = dirname(dir)) {
    if (existsSync(join(dir, '.git'))) return dir;
    if (dirname(dir) === dir) return null;
  }
}

export function shipsSomething(commit, paths) {
  const files = commit?.files;
  if (!paths || !Array.isArray(files) || !files.length) return true;
  return files.some((f) => paths.some((p) => (p.endsWith('/') ? f.startsWith(p) : f === p)));
}

export const terms = {
  'unreleased-commits': {
    signals: ['commits'],
    holds(signals) {
      const list = signals?.commits?.list ?? [];
      const above = unreleasedCommits(list);
      const paths = above.length ? readDeployedPaths() : null;
      const unreleased = above.filter((c) => shipsSomething(c, paths));
      if (above.length && !unreleased.length) {
        return { holds: false, reason: `the ${above.length} commit(s) since the last release changed nothing the deploy ships (${paths.join(', ')})` };
      }
      if (!unreleased.length) {
        return {
          holds: false,
          reason: list.length
            ? 'the newest default-branch commit is the last release itself — nothing has landed since it'
            : 'no commit landed on the default branch in the window',
        };
      }
      return {
        holds: true,
        reason: `${unreleased.length} commit(s) landed on the default branch since the last release`,
        context: [`Releasing ${unreleased.length} commit(s), newest first: ${unreleased.map((c) => String(c.sha ?? '?').slice(0, 7)).join(', ')}.`],
      };
    },
  },
};
// What the previous host left behind, evaluated rather than listed.
//
// A repo moving onto Cloudflare inherits whatever was already answering for its
// hostnames — most often records the zone import copied from the old host. Two of
// them matter, and both are invisible in the repo:
//
//   - a CNAME on a claimed hostname: a custom domain cannot be attached over one
//     (https://developers.cloudflare.com/workers/configuration/routing/custom-domains/),
//     so the deploy fails on that route;
//   - GitHub Pages' apex addresses: the attach succeeds, and visitors keep reaching
//     the old host until the records go.
//
// So the release asks public DNS what each claimed hostname currently answers, and
// parks naming the record it found. The alternative — an adoption checklist saying
// "delete any inherited records, if there are any" — is a step that is a no-op for
// most adopters, which is how a checklist teaches its reader to skim it.
//
// The probe carries no credential: the Workers API token this task holds grants no
// DNS read, and public resolution answers the question that matters anyway — what a
// visitor's resolver returns. An unreachable resolver is INCONCLUSIVE, never a
// verdict: the release proceeds and says the probe did not run.

// GitHub Pages' four apex addresses, published in
// https://docs.github.com/pages/configuring-a-custom-domain-for-your-github-pages-site
export const PAGES_ADDRESSES = new Set([
  '185.199.108.153', '185.199.109.153', '185.199.110.153', '185.199.111.153',
- **Model:** Opus 5

## 2026-09-22 · converted · The work step is declared as `code_worker_mjs` and the runner wraps it
- **Reason:** every worker re-implemented the same wrapping - the environment parsed by hand, the
  exit code, the failure line, the elapsed time, the agent-request file - and each copy was free to
  get it slightly differently wrong. The runner already owns the subprocess, so it owns the entry
  point: the module exports `worker(params)` and holds the work and nothing else.
- **Mechanism:** `code_worker_mjs` names the module beside the declaration; the executor spawns
  `claudinite-tasks`' own `worker-entry.mjs` around it, hands the module the parsed `CLAUDINITE_*`
  bag (the task's declared secrets and the Action token among it) and renders the verdict it returns
  into the queue's triage, requeue and agent-request protocol. No behaviour of the task changes: the
  same work runs, exits the same way and prints the same markers.
- **Actor:** @missingbulb (owner), who asked why every task re-implements one runner's job.
- **Model:** Opus 5

## 2026-10-20 · policy-changed · A commit that changes only documentation does not start a release
- **Reason:** a documentation commit, such as a design record under `docs/`, released the site
  under a fresh version number with byte-identical pages. Markdown inside the assets tree is held
  out of the upload by `.assetsignore` and `docs/` sits outside it, so such a commit ships nothing.
- **Mechanism:** `unreleased-commits` drops every commit above the last release whose files are all
  Markdown or under `docs/`, read from the `commits` signal's per-commit `files`. A commit with no
  file list counts as a change, so an engine that does not list files still releases.
- **Actor:** @missingbulb (owner), who asked that a documentation update not cause a release.
- **Model:** Opus 5.5

## 2026-10-20 · policy-changed · A release counts only commits that touch a deployed path
- **Reason:** the documentation exclusion named what does not ship, so any other file outside the
  deploy (a wiki page, a workflow) still released identical bytes. The owner asked for the gate to
  name what does ship instead.
- **Mechanism:** `unreleased-commits` reads the repo's wrangler config from the scheduler's checkout
  and counts a commit only when one of its files is under `deployedPaths`: the config, the
  published tree, the folder holding `main`, and the package manifests. A commit with no file list,
  or a repo whose config cannot be read there, still counts, so the release parks on the config
  problem by name. Supersedes the documentation exclusion of the same day.
- **Actor:** @missingbulb (owner).
- **Model:** Opus 5.5

