// The work half of the provenance convention: a change that alters a
// carrier's decision-bearing text carries the entry recording the
// decision, on the file the carrier names, in the same change. What owes:
// a rule or guideline whose marker-free text moved, a skill whose text
// moved beyond whitespace, the marking pass's own edits and (for a
// guidelines skill) its bullets, a check, task or manifest whose
// non-comment content moved. A pack with no provenance folder at the base
// is coming onto the convention, and owes nothing.
//
// A provenance file is meant to grow, and one that lost or altered a base
// line is advised, never refused: the rewrite that is right, the backfill,
// is the diff's to show. Several carriers may name one file; a carrier
// deleted while another still names its file owes an entry there, and
// only a file nothing names any more must end retired.
var provenanceChangeRecorded = declared.Builtin{
	ID:     "provenance-change-recorded",
	Pack:   "claudinite",
	OnFail: "block",
	Since:  "2026-09-20",
	Tags:   []string{"work", "builtin", "claudinite"},
	Doc:    "packs/claudinite/skills/changing-pack-elements/SKILL.md",
	Why:    "the decision behind a change exists only in the head of whoever made it, at the moment they made it; a log appended later is a reconstruction",
}

func init() { builtin.Register(&provenanceChangeRecorded, runProvenanceChangeRecorded) }

// baseIO reads the merge base, its directories off files. The files are
// read in one batch up front, and a path not among them is absent.
type baseIO struct {
	ctx   *declared.Ctx
	files []string
	has   map[string]bool
}

func newBaseIO(ctx *declared.Ctx, files []string) baseIO {
	has := map[string]bool{}
	for _, f := range files {
		has[f] = true
	}
	ctx.PrefetchBase(files)
	return baseIO{ctx, files, has}

// The world half of the provenance convention: every carrier of every
// pack under either root (a canon's shelf, a member's local packs) names
// a live provenance file, every file parses, and a file with entries
// opens with born and carries Mechanism where its kind demands. The mount
// is never scanned. A fault that repeats in one file is one finding naming
// the count, and pending history (an empty file) is one advisory per
// pack.
var provenanceIntegrity = declared.Builtin{
	ID:     "provenance-integrity",
	Pack:   "claudinite",
	OnFail: "block",
	Since:  "2026-09-20",
	Tags:   []string{"world", "builtin", "claudinite"},
	Doc:    "packs/claudinite/skills/changing-pack-elements/SKILL.md",
	Why:    "a rule with no file has no id an override can name and no log a review can reaffirm it against, and a file nothing names is history of an element that is gone",
}

func init() { builtin.Register(&provenanceIntegrity, runProvenanceIntegrity) }

// growthTool is the provenance CLI a finding's remedy names.
const growthTool = "cn provenance"

// treeIO reads the working tree, its directories off the run's scanned
// files, so an audit walks exactly what the run scans.
func treeIO(ctx *declared.Ctx) provenance.IO {
