// record, and losing it costs more than a misshapen one.
func Appended(existing string, e Entry, kinds []string, firstKind string) (string, []string) {
	warnings := Problems(e, kinds)
	entries, errs := prov.ParseKinds(existing, kinds)
	if len(errs) > 0 {
		warnings = append(warnings, fmt.Sprintf("the file does not parse (line %d: %s)", errs[0].Line, errs[0].What))
	}
	if n := len(entries); n > 0 {
		last := entries[n-1]
		if e.Date < last.Date {
			warnings = append(warnings, "the file's last entry is dated "+last.Date+"; an entry is appended in date order")
		}
		if last.Kind == "retired" {
			warnings = append(warnings, "the element is retired; an entry after its retirement reads as a revival")
		}
	} else if firstKind != "" && e.Kind != firstKind {
		warnings = append(warnings, "the first entry of a file is "+firstKind+", not "+e.Kind)
	}
	return joined(existing, Render(e)), warnings
}

// joined is body appended to existing, one blank line between them.
func joined(existing, body string) string {
	if strings.TrimSpace(existing) == "" {
		return body
	}
	glue := "\\n\\n"
	switch {
	case strings.HasSuffix(existing, "\\n\\n"):
		glue = ""
	case strings.HasSuffix(existing, "\\n"):
		glue = "\\n"
	}
	return existing + glue + body
}

